struct SpyMailer { calls: RefCell<Vec<(String, String)>> }
impl Mailer for SpyMailer {
    fn send(&self, to: String, body: String) {
        self.calls.borrow_mut().push((to, body));
    }
}
let spy = SpyMailer::default();
OrderService::new(&spy).place(order);
assert_eq!(
    spy.calls.borrow().as_slice(),
    &[("bob@example.com".to_string(), body)]
);
